def get_logger() -> logging.Logger:
    try:
        parser = argparse.ArgumentParser(add_help=False, exit_on_error=False)
    except TypeError:
        parser = argparse.ArgumentParser(add_help=False)
        
    parser.add_argument('-d', '--debug', action='count', default=0)
    known_args, _ = parser.parse_known_args()

    verbosity = known_args.debug

    level = logging.ERROR
    if verbosity == 1:
        level = logging.WARNING
    elif verbosity == 2:
        level = logging.INFO
    elif verbosity >= 3:
        level = logging.DEBUG

    logging.basicConfig(level=level)
    return logging.getLogger("ResultParser")

logger = get_logger()

class ResultBuilder:
    def __init__(self):
        self.__cpu_core_count: Optional[int] = None
        self.__cpu_name: Optional[str] = None
        self.__date: Optional[str] = None
        self.__compiler: Optional[str] = None
        self.__version: Optional[str] = None
        self.__comment: Optional[str] = None
        self.__results_dataframe = None

    def get(self):
        if not self.__results_dataframe:
            raise ValueError("No valid dataframe table found in the input file. The file might be corrupted or in an unsupported format.")
            
        return {
            'system_info': {
                'compiler_info': self.__compiler,
                'version_info': self.__version if self.__version else 'Unknown',
                'cpu_name': self.__cpu_name,
                'cpu_core_count': self.__cpu_core_count,
            },
            'timestamp': self.__date,
            'comment': self.__comment,
            'full_result': self.__parse_dataframe()
        }

    def set_comment(self, comment: str):
        self.__comment = comment
        return self

    def set_version(self, version: str):
        self.__version = version
        return self

    def set_compiler(self, compiler: str):
        self.__compiler = compiler
        return self

    def set_date(self, date: str):
        self.__date = date
        return self

    def set_cpu_name(self, cpu_name: str):
        self.__cpu_name = cpu_name
        return self

    def set_cpu_core_count(self, cpu_core_count: int):
        self.__cpu_core_count = cpu_core_count
        return self

    def set_result_dataframe(self, dataframe):
        if len(dataframe) != 48:
            raise RuntimeError(f"Results dataframe received is not expected size of 48, received {len(dataframe)}")
        self.__results_dataframe = dataframe
        return self

    def __parse_dataframe(self):
        class Optimization(IntEnum):
            NON_OPTIMIZED = 0
            OPTIMIZED = 1

        class RunType(IntEnum):
            MANUAL = 0
            SINGLE_CORE = 1
            MULTI_CORE = 2
            QUAD_CORE = 3
            WORKSTATION = 4

        column_count = len(self.__results_dataframe[0])

        full_result = list()

        first_dataframe, second_dataframe = self.__split_dataframe(self.__results_dataframe)
        if self.__get_dataframe_average(first_dataframe) > self.__get_dataframe_average(second_dataframe):
            optimized_dataframe, non_optimized_dataframe = first_dataframe, second_dataframe
        else:
            optimized_dataframe, non_optimized_dataframe = second_dataframe, first_dataframe

        for optimization in Optimization:
            full_result.append({'detailed': []})
            for _ in RunType:
                full_result[optimization]['detailed'].append({'valid': False})

        runs_types = {
            1: [RunType.MANUAL],
            2: [RunType.SINGLE_CORE, RunType.MULTI_CORE],
            3: [RunType.SINGLE_CORE, RunType.MULTI_CORE, RunType.QUAD_CORE],
            4: [RunType.SINGLE_CORE, RunType.MULTI_CORE, RunType.QUAD_CORE, RunType.WORKSTATION]
        }[column_count]

        for i, run in enumerate(runs_types):
            full_result[Optimization.NON_OPTIMIZED]['detailed'][run]['valid'] = True
            full_result[Optimization.NON_OPTIMIZED]['detailed'][run]['kernels'] = []
            for row in non_optimized_dataframe:
                full_result[Optimization.NON_OPTIMIZED]['detailed'][run]['kernels'].append(row[i])

            full_result[Optimization.OPTIMIZED]['detailed'][run]['valid'] = True
            full_result[Optimization.OPTIMIZED]['detailed'][run]['kernels'] = []
            for row in optimized_dataframe:
                full_result[Optimization.OPTIMIZED]['detailed'][run]['kernels'].append(row[i])

        for run in full_result:
            for run_type in runs_types:
                run_type = run['detailed'][run_type]
                kernels = run_type['kernels']
                run_type['maximum'] = max(kernels)
                run_type['average'] = sum(kernels) / len(kernels)
                run_type['minimum'] = min(kernels)

                run_type['geometric'] = self.__geometric(kernels)
                run_type['harmonic'] = self.__harmonic(kernels)
                run_type['score'] = run_type['geometric']

        for run in full_result:
            for run_type in runs_types:
                run_type = run['detailed'][run_type]
                run_type['ratio'] = run_type['score'] / run['detailed'][RunType.SINGLE_CORE]['score']
            run['score'] = self.__geometric([run['detailed'][x]['geometric'] for x in runs_types if x is not RunType.WORKSTATION])
            run['optimized_ratio'] = run['score'] / full_result[Optimization.NON_OPTIMIZED]['score']

        return full_result
        
    @staticmethod
    def __geometric(iterable):
        return math.exp(sum(math.log(x) for x in iterable) / len(iterable))

    @staticmethod
    def __harmonic(iterable):
        return len(iterable) / sum(1 / x for x in iterable)

    @staticmethod
    def __split_dataframe(data):
        mid = len(data) // 2
        return data[:mid], data[mid:]

    @staticmethod
    def __get_dataframe_average(data):
        sum = 0
        count = 0
        for data_row in data:
            for data_cell in data_row:
                sum += data_cell
                count += 1
        return sum / count

class ResultParser:
    def __init__(self, data):
        self.__result = ResultBuilder()
        self.data = data
        pass

    def find(self, pattern, flags=re.IGNORECASE | re.MULTILINE):
        match = re.search(pattern, self.data, flags=flags)
        if match:
            return match.groups()[-1]
        return None

    @staticmethod
    def __to_dataframe(data, remove_first_column: bool = True):
        while type(data) is list and type(data[0]) in [list, str]:
            new_data = []
            for value in data:
                if type(value) is str:
                    value = re.findall(r'\d+\.?\d*', value)
                    new_data.extend([float(value) for value in value])
                elif type(value) is list:
                    new_data.extend(value)
            data = new_data

        columns = len(data) // (24 * 2)
        if columns == 0:
             raise ValueError("Extracted columns calculate to 0. Invalid data formatting.")
             
        rows = len(data) // columns

        data = [data[i * columns + (1 if remove_first_column else 0):(i + 1) * columns] for i in range(rows)]
        return data

    def parse_text(self):
        logger.debug(f"{__name__} enter")

        version_match = re.search(r'(?:version).*?- (.*)', self.data, flags=re.IGNORECASE)
        if version_match:
            self.__result.set_version(version_match.groups()[0])

        compiler_match = re.search(r'(?:compiler).*?- (.*)', self.data, flags=re.IGNORECASE)
        if compiler_match:
            self.__result.set_compiler(compiler_match.groups()[0])

        cpu_name_match = re.search(r'(?:cpu name|cpu|processor).*?- (.*)', self.data, flags=re.IGNORECASE)
        if cpu_name_match:
            self.__result.set_cpu_name(cpu_name_match.groups()[0])

        cpu_core_count_match = re.search(r'(?:logical cores|threads|cores|core count).*?- (.*)', self.data, flags=re.IGNORECASE)
        if cpu_core_count_match:
            self.__result.set_cpu_core_count(int(cpu_core_count_match.groups()[0]))

        date_match = re.search(r'(?:date|timestamp).*?- (.*)', self.data, flags=re.IGNORECASE)
        if date_match:
            self.__result.set_date(date_match.groups()[0])

        comment_match = re.search(r'(?:comment).*?- (.*)', self.data, flags=re.IGNORECASE)
        if comment_match:
            self.__result.set_comment(comment_match.groups()[0])

        parsed_successfully = False
        for table_column_count in [5, 4, 3, 2]:
            logger.debug(f"Trying {table_column_count} columns parsing")
            if len(re.findall(r'((?:[^\n\w\.]+[\.\d]+){{{}}})'.format(table_column_count), self.data)) < 48:
                continue
            raw_tables_values = re.findall(r'\n((?:\W+[\.\d]+){{{}}})'.format(table_column_count * 24), self.data)
            df = self.__to_dataframe(raw_tables_values)
            self.__result.set_result_dataframe(df)
            parsed_successfully = True
            break
            
        if not parsed_successfully:
             raise ValueError("Could not extract a valid 24-loop table matrix from the TXT data.")

        return self.__result.get()

    def parse_html(self):
        self.data = self.data.replace('\n', '')
        self.data = self.data.replace('\t', '')

        version_match = re.search(r'<td>(?:version).*?<td.*?>(\w.*?)</td>', self.data, flags=re.IGNORECASE)
        if version_match:
            self.__result.set_version(version_match.groups()[0])

        compiler_match = re.search(r'<td>(?:compiler).*?<td.*?>(\w.*?)</td>', self.data, flags=re.IGNORECASE)
        if compiler_match:
            self.__result.set_compiler(compiler_match.groups()[0])

        cpu_name_match = re.search(r'<td>(?:cpu name|cpu|processor).*?<td.*?>(\w.*?)</td>', self.data, flags=re.IGNORECASE)
        if cpu_name_match:
            self.__result.set_cpu_name(cpu_name_match.groups()[0])

        cpu_core_count_match = re.search(r'<td>(?:logical cores|threads|cores|core count).*?<td.*?>(\w.*?)</td>', self.data, flags=re.IGNORECASE)
        if cpu_core_count_match:
            self.__result.set_cpu_core_count(int(cpu_core_count_match.groups()[0]))

        date_match = re.search(r'<td>(?:date|timestamp).*?<td.*?>(\w.*?)</td>', self.data, flags=re.IGNORECASE)
        if date_match:
            self.__result.set_date(date_match.groups()[0])

        comment_match = re.search(r'<td>(?:comment).*?<td.*?>(.*?)</td>', self.data, flags=re.IGNORECASE)
        if comment_match:
            self.__result.set_comment(comment_match.groups()[0])

        raw_data = []
        table_rows = re.findall(r'<tr>.*?</tr>', self.data)

        for table_column_count in [4, 3, 2, 1]:
            for table_row in table_rows:
                if re.search(f'<tr><td>[\\d\\.]+</td>.*?(<td>[\\d\\.]+</td>){{{table_column_count}}}</tr>', table_row):
                    raw_data.append(re.findall(f'((?:<td>[\\d\\.]+</td>){{{table_column_count}}})</tr>', table_row))
            if raw_data:
                break
                
        if not raw_data:
             raise ValueError("Could not extract a valid table matrix from the HTML data.")

        df = self.__to_dataframe(raw_data, remove_first_column=False)
        self.__result.set_result_dataframe(df)

        return self.__result.get()

    def parse(self, filetype):
        if filetype == FileType.TEXT:
            return self.parse_text()
        elif filetype == FileType.HTML:
            return self.parse_html()

class FileType(Enum):
    TEXT = 1
    HTML = 2

def parse_arguments():
    parser = argparse.ArgumentParser(description="Evolution benchmark result parser")
    parser.add_argument('file', type=str, help='Path to the input file')
    parser.add_argument('-d', '--debug', action='count', default=0, help='Increase verbosity (use -d, -dd, -ddd)')
    return parser.parse_args()

def read_file(filepath):
    encodings = ["utf-8", "cp1252", "iso-8859-1"]
    for enc in encodings:
        try:
            with open(filepath, "r", encoding=enc, errors="replace") as file:
                return file.read()
        except UnicodeDecodeError:
            continue
    raise ValueError("File encoding could not be determined.")

def main():
    args = parse_arguments()
    logger.debug(f"Arguments: {args}")

    filename = args.file

    if filename.endswith('.html') or filename.endswith('.htm'):
        filetype = FileType.HTML
    elif filename.endswith('.txt'):
        filetype = FileType.TEXT
    else:
        logger.error(f"File {filename} does not have a supported file extension (.txt or .html).")
        sys.exit(1)
        
    logger.info(f"Detected file extension is {filetype}")

    try:
        data = read_file(filename)
    except Exception as e:
        logger.error(f"Failed to read file {filename}. Error: {e}")
        sys.exit(1)

    parser = ResultParser(data)
    
    try:
        result = parser.parse(filetype)
    except Exception as e:
        logger.error(f"Failed to parse the benchmark results. Error: {e}")
        logger.debug("Ensure the file contains valid Waverian Evolution benchmark data tables.")
        sys.exit(1)

    # Output naming logic
    base_name = filename.rsplit('.', 1)[0]
    out_html = f"{base_name}.html"
    out_txt = f"{base_name}_updated.txt"

    # HTML Generation
    try:
        with open(out_html, 'w', encoding='utf-8') as file:
            py_print_html(file, result)
        logger.info(f"Successfully generated HTML report: {out_html}")
    except Exception as e:
        logger.error(f"Failed to write HTML file {out_html}: {e}")

    # Version Logic for TXT Generation
    version_str = result.get("system_info", {}).get("version_info", "0.0.0")
    is_current = False
    try:
        v_match = re.search(r'(\d+)\.(\d+)', version_str)
        if v_match:
            major, minor = int(v_match.group(1)), int(v_match.group(2))
            if major > 3 or (major == 3 and minor >= 3):
                is_current = True
    except Exception:
        pass

    if is_current and filetype == FileType.TEXT:
        logger.info(f"Detected current version ({version_str} >= 3.3.0). Skipping TXT generation.")
    else:
        try:
            with open(out_txt, 'w', encoding='utf-8') as file:
                py_print(file, result)
            logger.info(f"Successfully generated TXT report: {out_txt}")
        except Exception as e:
            logger.error(f"Failed to write TXT file {out_txt}: {e}")

if __name__ == "__main__":
    main()